<script setup lang="ts">
import { BookOpenCheck, Check, ClipboardCheck, FileUp, LoaderCircle, Plus, Save, X } from '@lucide/vue'
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import api from '../api'
import { useLocaleStore } from '../stores/locale'

const router=useRouter();const locale=useLocaleStore();const loading=ref(true);const saving=ref(false);const marksSaving=ref(false);const statusSaving=ref(false);const importing=ref(false);const open=ref(false);const error=ref('');const importMessage=ref('');const importErrors=ref<any[]>([]);const exams=ref<any[]>([]);const groups=ref<any[]>([]);const subjects=ref<any[]>([]);const selectedExam=ref<any>(null);const students=ref<any[]>([]);const markRows=ref<Record<number,{mark:string;comment:string}>>({});const importFile=ref<File|null>(null);const form=ref({title:'',subject_id:'',teaching_group_ids:[] as number[],exam_date:new Date().toISOString().slice(0,10),total_marks:100,notes:''});const selectedCount=computed(()=>form.value.teaching_group_ids.length)
async function load(){loading.value=true;try{const [e,g,d]=await Promise.all([api.get('/examinations'),api.get('/teaching-groups'),api.get('/dashboard')]);exams.value=e.data.exams||[];groups.value=g.data.groups||[];subjects.value=d.data.subjects||[]}catch(e:any){error.value=e.response?.data?.message||'Unable to load examinations.'}finally{loading.value=false}}
async function createExam(){saving.value=true;error.value='';try{const r=await api.post('/examinations',{...form.value,subject_id:Number(form.value.subject_id),total_marks:Number(form.value.total_marks)});exams.value.unshift(r.data.exam);selectedExam.value=r.data.exam;open.value=false;await selectExam(selectedExam.value)}catch(e:any){error.value=e.response?.data?.message||'Unable to create this exam.'}finally{saving.value=false}}
async function selectExam(exam:any){if(selectedExam.value?.id===exam.id){router.push(`/teacher/exams/${exam.id}/attendance`);return}selectedExam.value=exam;importMessage.value='';importErrors.value=[];try{const r=await api.get(`/examinations/${exam.id}/marks`);students.value=r.data.students||[];const rows:Record<number,{mark:string;comment:string}>={};students.value.forEach((s:any)=>{const m=(r.data.marks||[]).find((x:any)=>x.student_id===s.id);rows[s.id]={mark:m?.mark??'',comment:m?.comment??''}});markRows.value=rows}catch(e:any){error.value=e.response?.data?.message||'Unable to load marks for this exam.'}}
async function saveMarks(){if(!selectedExam.value)return;marksSaving.value=true;try{await api.put(`/examinations/${selectedExam.value.id}/marks`,{marks:Object.entries(markRows.value).filter(([,r])=>r.mark!=='').map(([id,r])=>({student_id:Number(id),mark:Number(r.mark),comment:r.comment||null}))});selectedExam.value.marks_count=Object.values(markRows.value).filter(r=>r.mark!=='').length}catch(e:any){error.value=e.response?.data?.message||'Unable to save marks.'}finally{marksSaving.value=false}}
async function changeStatus(status:'published'|'locked'){if(!selectedExam.value)return;statusSaving.value=true;try{const r=await api.post(`/examinations/${selectedExam.value.id}/status`,{status});selectedExam.value=r.data.exam;const i=exams.value.findIndex(e=>e.id===selectedExam.value.id);if(i>=0)exams.value[i]=r.data.exam}catch(e:any){error.value=e.response?.data?.message||'Unable to update this exam status.'}finally{statusSaving.value=false}}
function chooseFile(event:Event){importFile.value=(event.target as HTMLInputElement).files?.[0]||null;importMessage.value='';importErrors.value=[]}
async function importMarks(){if(!selectedExam.value||!importFile.value)return;importing.value=true;error.value='';importMessage.value='';importErrors.value=[];const body=new FormData();body.append('file',importFile.value);try{const r=(await api.post(`/examinations/${selectedExam.value.id}/marks/import`,body,{headers:{'Content-Type':'multipart/form-data'}})).data;importMessage.value=`${r.imported} ${locale.tr('marks imported')}`;importErrors.value=r.errors||[];await selectExam(selectedExam.value)}catch(e:any){error.value=e.response?.data?.message||'Unable to import marks.'}finally{importing.value=false}}
function focusNext(e:KeyboardEvent,i:number){if(e.key==='Enter'){e.preventDefault();document.querySelectorAll<HTMLInputElement>('.marks-table input.mark-input')[i+1]?.focus()}}
onMounted(load)
</script>
<template><div class="app-shell teacher-shell exams-workspace"><main class="dashboard-main"><header><button class="button secondary back-button" @click="router.push('/teacher/overview')">{{locale.tr('Teacher workspace')}}</button></header><div v-if="loading" class="loading-state"><span></span>{{locale.tr('Loading examinations…')}}</div><div v-else class="dashboard-content teacher-content"><div class="teacher-page-head"><div><span>{{locale.tr('ASSESSMENT HUB')}}</span><h1>{{locale.tr('Exams & marks')}}</h1><p>{{locale.tr('Create assessments, target your groups, and enter marks without leaving the page.')}}</p></div><button class="button primary" @click="open=true"><Plus/>{{locale.tr('Create exam')}}</button></div><div v-if="error" class="form-error">{{error}}</div><section class="exam-workspace"><div class="teacher-card exam-list"><div class="teacher-card-head"><div><small>{{locale.tr('ASSESSMENTS')}}</small><h2>{{locale.tr('Your examinations')}}</h2></div><ClipboardCheck/></div><button v-for="exam in exams" :key="exam.id" class="exam-row" :class="{selected:selectedExam?.id===exam.id}" @click="selectExam(exam)"><span class="exam-icon"><BookOpenCheck/></span><span><b>{{exam.title}}</b><small>{{exam.subject?.name_en||exam.subject?.name_ar||'Subject'}} · {{exam.exam_date}}</small></span><strong>{{exam.marks_count||0}} / {{exam.total_marks}}</strong><em :class="exam.status">{{locale.tr(exam.status)}}</em></button><div v-if="!exams.length" class="teacher-empty compact"><ClipboardCheck/><b>{{locale.tr('No examinations yet')}}</b><p>{{locale.tr('Create your first assessment for a teaching group.')}}</p></div></div><section class="marks-panel" :class="{empty:!selectedExam}"><template v-if="selectedExam"><div class="teacher-card-head"><div><small>{{locale.tr('MARKS ENTRY')}}</small><h2>{{selectedExam.title}}</h2><p class="marks-subtitle">{{selectedExam.exam_date}} · {{selectedExam.total_marks}} {{locale.tr('marks')}} · {{locale.tr(selectedExam.status)}}</p></div><div class="exam-status-actions"><label v-if="selectedExam.status!=='locked'" class="exam-import-button"><FileUp/><input type="file" accept=".csv,.txt" @change="chooseFile">{{importFile?.name||locale.tr('Choose CSV')}}</label><button v-if="importFile&&selectedExam.status!=='locked'" class="button secondary" :disabled="importing" @click="importMarks"><LoaderCircle v-if="importing" class="spin"/><FileUp v-else/>{{importing?locale.tr('Importing…'):locale.tr('Import marks')}}</button><button v-if="selectedExam.status==='draft'" class="button secondary" :disabled="statusSaving" @click="changeStatus('published')">{{locale.tr('Publish results')}}</button><button v-if="selectedExam.status==='published'" class="button secondary" :disabled="statusSaving" @click="changeStatus('locked')">{{locale.tr('Lock exam')}}</button><button class="button primary" :disabled="marksSaving||selectedExam.status==='locked'" @click="saveMarks"><LoaderCircle v-if="marksSaving" class="spin"/><Save v-else/>{{marksSaving?locale.tr('Saving…'):locale.tr('Save marks')}}</button></div></div><div v-if="importMessage" class="import-message">{{importMessage}}</div><div v-if="importErrors.length" class="import-errors"><b>{{locale.tr('Rows needing attention')}}</b><span v-for="item in importErrors" :key="item.row">{{locale.tr('Row')}} {{item.row}}: {{item.message}}</span></div><div v-if="!students.length" class="teacher-empty compact"><BookOpenCheck/><b>{{locale.tr('No students targeted')}}</b><p>{{locale.tr('Choose one or more teaching groups when creating the exam.')}}</p></div><div v-else class="marks-table-wrap"><table class="marks-table"><thead><tr><th>{{locale.tr('Student')}}</th><th>{{locale.tr('Code')}}</th><th>{{locale.tr('Mark')}}</th><th>{{locale.tr('Comment')}}</th></tr></thead><tbody><tr v-for="(student,index) in students" :key="student.id"><td><b>{{student.name_en||student.name_ar}}</b></td><td>{{student.student_code}}</td><td><input class="mark-input" type="number" min="0" :max="selectedExam.total_marks" step="0.5" v-model="markRows[student.id].mark" @keydown="focusNext($event,index)"></td><td><input type="text" v-model="markRows[student.id].comment" :placeholder="locale.tr('Optional note')"></td></tr></tbody></table></div></template><div v-else class="teacher-list-empty"><BookOpenCheck/><h2>{{locale.tr('Select an examination')}}</h2><p>{{locale.tr('Select an exam to enter marks, or create a new one to get started.')}}</p></div></section></section></div></main><div v-if="open" class="modal-backdrop" @click.self="open=false"><section class="centre-modal exam-modal" role="dialog"><div class="modal-header"><div><span class="modal-icon"><Plus/></span><span class="eyebrow">{{locale.tr('NEW ASSESSMENT')}}</span><h2>{{locale.tr('Create exam')}}</h2></div><button class="modal-close" @click="open=false"><X/></button></div><div class="modal-body"><form @submit.prevent="createExam"><label>{{locale.tr('Title')}}<input v-model="form.title" required></label><div class="modal-grid"><label>{{locale.tr('Subject')}}<select v-model="form.subject_id" required><option value="" disabled>{{locale.tr('Select subject')}}</option><option v-for="subject in subjects" :key="subject.id" :value="subject.id">{{subject.name_en||subject.name_ar}}</option></select></label><label>{{locale.tr('Exam date')}}<input v-model="form.exam_date" type="date" required></label></div><div class="modal-grid"><label>{{locale.tr('Total marks')}}<input v-model="form.total_marks" type="number" min="1" required></label><label>{{locale.tr('Notes')}}<input v-model="form.notes"></label></div><fieldset class="exam-group-picker"><legend>{{locale.tr('Teaching groups')}} <small>({{selectedCount}} {{locale.tr('selected')}})</small></legend><label v-for="group in groups" :key="group.id"><input v-model="form.teaching_group_ids" type="checkbox" :value="group.id"><span>{{group.name_en||group.name_ar}} · {{group.code}}</span></label></fieldset><div class="modal-actions"><button type="button" class="button secondary" @click="open=false">{{locale.tr('Cancel')}}</button><button class="button primary" :disabled="saving">{{saving?locale.tr('Creating…'):locale.tr('Create exam')}}<Check/></button></div></form></div></section></div></div></template>
